public int sansaXor(int[] arr) {
    int result = 0;
    int n = arr.length;
    for (int i = 0; i < n; i++) {
        int running = 0;
        for (int j = i; j < n; j++) {
            running ^= arr[j];     // XOR of arr[i..j]
            result ^= running;     // fold this subarray's XOR in
        }
    }
    return result;
}

