def sansaXor(arr: list[int]) -> int:
    result = 0
    n = len(arr)
    for i in range(n):
        running = 0
        for j in range(i, n):
            running ^= arr[j]      # XOR of arr[i..j]
            result ^= running      # fold this subarray's XOR in
    return result

