code.java:
public int sansaXor(int[] arr) {
    int n = arr.length;
    if (n % 2 == 0) return 0;          // every count even → all cancel
    int result = 0;
    for (int i = 0; i < n; i += 2) {   // even indices only
        result ^= arr[i];
    }
    return result;
}

